  function draw(t) { const age = DeskWorld.seconds(performance.now(), 0); ctx.clearRect(0, 0, W, H); if (ID === 'sky') drawSky(age); else if (ID === 'beach-turquoise') drawMaldives(age); else if (ID === 'lake') drawLake(age); else if (ID === 'ocean') drawOcean(age, true); else if (ID === 'forest') drawForest(age); else if (ID === 'pinkforest') drawForest(age, true); else if (ID === 'map') drawCity(age); else if (ID === 'citymap') drawCity(age, true); else if (ID === 'worldmap') drawMap(age); else if (ID === 'nauticalmap') drawMap(age, true); else if (ID === 'lotus') drawLotus(age); else drawOcean(age, false); drawPreviewIcons(); }
